using System.Data.Common;
using Careflow.Application;
using Careflow.Domain;
namespace Careflow.Infrastructure;

// SQL Server IHospitalStore slice for Phase 5: quality/accreditation, patient
// portal and management reporting.

public sealed partial class SqlHospitalStore
{
    // ---- quality ------------------------------------------------------------
    private static Infection MapInfection(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), G(r, "PatientId"), GN(r, "EncounterId"), S(r, "Category"), S(r, "Site"), S(r, "DetectedMethod"), Date(r, "DetectedOn"), S(r, "Severity"), S(r, "Status"), S(r, "ReportedBy"), T(r, "ReportedAtUtc"), S(r, "Investigation"), S(r, "Outcome"), L(r, "Version"));
    private static Incident MapIncident(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), S(r, "Category"), S(r, "Severity"), S(r, "Description"), S(r, "Location"), GN(r, "PatientId"), S(r, "ReportedBy"), T(r, "ReportedAtUtc"), S(r, "Status"), S(r, "TriageNote"), S(r, "AssignedTo"), TN(r, "TriagedAtUtc"), S(r, "Investigation"), S(r, "RootCause"), L(r, "Version"));
    private static RiskAssessment MapRisk(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), S(r, "Domain"), S(r, "Description"), I(r, "Probability"), I(r, "Impact"), S(r, "Mitigation"), S(r, "Owner"), S(r, "Status"), T(r, "AssessedAtUtc"), L(r, "Version"));
    private static Capa MapCapa(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), GN(r, "IncidentId"), GN(r, "InfectionId"), GN(r, "AuditId"), GN(r, "RiskId"), S(r, "Correction"), S(r, "CorrectiveAction"), S(r, "PreventiveAction"), S(r, "Owner"), T(r, "DueAtUtc"), S(r, "Status"), S(r, "EffectivenessEvidence"), B(r, "EffectivenessVerified"), S(r, "VerifiedBy"), TN(r, "VerifiedAtUtc"), T(r, "CreatedAtUtc"), S(r, "CreatedBy"), L(r, "Version"));
    private static ClinicalAudit MapAudit(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), S(r, "Domain"), S(r, "Scope"), Date(r, "PlannedFor"), S(r, "Lead"), S(r, "Status"), S(r, "Findings"), I(r, "ScorePercent"), S(r, "Report"), T(r, "CreatedAtUtc"), S(r, "CreatedBy"), L(r, "Version"));
    private static QualityIndicator MapQualityIndicator(DbDataReader r) => new(G(r, "Id"), S(r, "Code"), S(r, "Name"), S(r, "Definition"), S(r, "Numerator"), S(r, "Denominator"), S(r, "Period"), S(r, "Owner"), S(r, "Status"), L(r, "Version"));
    private static IndicatorResult MapQualityIndicatorResult(DbDataReader r) => new(G(r, "Id"), G(r, "IndicatorId"), S(r, "PeriodStart"), S(r, "PeriodEnd"), DN(r, "Numerator")!.Value, DN(r, "Denominator")!.Value, DN(r, "Value")!.Value, S(r, "Basis"), S(r, "Note"), S(r, "RecordedBy"), T(r, "RecordedAtUtc"));
    private static QualityDocument MapDocument(DbDataReader r) => new(G(r, "Id"), S(r, "Number"), S(r, "Title"), S(r, "Category"), S(r, "Status"), I(r, "CurrentVersion"), S(r, "Owner"), T(r, "CreatedAtUtc"), L(r, "Version"));
    private static DocumentVersion MapDocumentVersion(DbDataReader r) => new(G(r, "Id"), G(r, "DocumentId"), I(r, "Number"), S(r, "Summary"), S(r, "Content"), S(r, "CreatedBy"), T(r, "CreatedAtUtc"), S(r, "ApprovedBy"), TN(r, "ApprovedAtUtc"));
    private static SopAcknowledgment MapSopAck(DbDataReader r) => new(G(r, "Id"), G(r, "DocumentId"), I(r, "VersionNumber"), S(r, "UserName"), S(r, "Attestation"), T(r, "AcknowledgedAtUtc"));

    public Task<Infection?> FindInfectionAsync(Guid id, CancellationToken ct) => Query("SELECT TOP(1) Id,Number,PatientId,EncounterId,Category,Site,DetectedMethod,DetectedOn,Severity,Status,ReportedBy,ReportedAtUtc,Investigation,Outcome,Version FROM quality.Infections WHERE HospitalId=@h AND Id=@id", MapInfection, H, ("id", id)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
    public Task InsertInfectionAsync(Infection x, CancellationToken ct) => Execute("INSERT INTO quality.Infections(Id,HospitalId,BranchId,Number,PatientId,EncounterId,Category,Site,DetectedMethod,DetectedOn,Severity,Status,ReportedBy,ReportedAtUtc,Investigation,Outcome,Version) VALUES(@id,@h,@b,@number,@patient,@encounter,@category,@site,@method,@on,@severity,@status,@by,@at,@investigation,@outcome,1)",
        ("id", x.Id), ("number", x.Number), ("patient", x.PatientId), ("encounter", (object?)x.EncounterId ?? DBNull.Value), ("category", x.Category), ("site", x.Site), ("method", x.DetectedMethod), ("on", x.DetectedOn), ("severity", x.Severity), ("status", x.Status), ("by", x.ReportedBy), ("at", x.ReportedAt), ("investigation", x.Investigation), ("outcome", x.Outcome), H, Branch);
    public async Task UpdateInfectionAsync(Infection x, CancellationToken ct)
    {
        if (await Execute("UPDATE quality.Infections SET Status=@status,Investigation=@investigation,Outcome=@outcome,Version=@new WHERE Id=@id AND HospitalId=@h AND Version=@old", ("status", x.Status), ("investigation", x.Investigation), ("outcome", x.Outcome), ("new", x.Version), ("id", x.Id), H, ("old", x.Version - 1)) != 1) throw Conflict();
    }
    public Task<IReadOnlyList<Infection>> ListInfectionsAsync(Guid? patientId, CancellationToken ct) => Query("SELECT Id,Number,PatientId,EncounterId,Category,Site,DetectedMethod,DetectedOn,Severity,Status,ReportedBy,ReportedAtUtc,Investigation,Outcome,Version FROM quality.Infections WHERE HospitalId=@h AND (@patient IS NULL OR PatientId=@patient) ORDER BY ReportedAtUtc DESC", MapInfection, H, ("patient", (object?)patientId ?? DBNull.Value)).ContinueWith(t => (IReadOnlyList<Infection>)t.Result, ct);

    public Task<Incident?> FindIncidentAsync(Guid id, CancellationToken ct) => Query("SELECT TOP(1) Id,Number,Category,Severity,Description,Location,PatientId,ReportedBy,ReportedAtUtc,Status,TriageNote,AssignedTo,TriagedAtUtc,Investigation,RootCause,Version FROM quality.Incidents WHERE HospitalId=@h AND Id=@id", MapIncident, H, ("id", id)).ContinueWith(t => t.Result.FirstOrDefault(), ct);
