        ("id", x.Id), ("number", x.Number), ("category", x.Category), ("severity", x.Severity), ("description", x.Description), ("location", x.Location), ("patient", (object?)x.PatientId ?? DBNull.Value), ("by", x.ReportedBy), ("at", x.ReportedAt), ("status", x.Status), ("note", x.TriageNote), ("assigned", x.AssignedTo), ("triaged", (object?)x.TriagedAt ?? DBNull.Value), ("investigation", x.Investigation), ("rootcause", x.RootCause), H, Branch);
    public async Task UpdateIncidentAsync(Incident x, CancellationToken ct)
    {
        if (await Execute("UPDATE quality.Incidents SET Status=@status,TriageNote=@note,AssignedTo=@assigned,TriagedAtUtc=@triaged,Investigation=@investigation,RootCause=@rootcause,Version=@new WHERE Id=@id AND HospitalId=@h AND Version=@old", ("status", x.Status), ("note", x.TriageNote), ("assigned", x.AssignedTo), ("triaged", (object?)x.TriagedAt ?? DBNull.Value), ("investigation", x.Investigation), ("rootcause", x.RootCause), ("new", x.Version), ("id", x.Id), H, ("old", x.Version - 1)) != 1) throw Conflict();
