    public Task<IReadOnlyList<Incident>> ListIncidentsAsync(CancellationToken ct) => Query("SELECT Id,Number,Category,Severity,Description,Location,PatientId,ReportedBy,ReportedAtUtc,Status,TriageNote,AssignedTo,TriagedAtUtc,Investigation,RootCause,Version FROM quality.Incidents WHERE HospitalId=@h ORDER BY ReportedAtUtc DESC", MapIncident, H).ContinueWith(t => (IReadOnlyList<Incident>)t.Result, ct);

