    public async Task<IReadOnlyList<Invoice>> ListInvoicesBriefAsync(CancellationToken ct)
    {
        var invoices = await Query("SELECT Id,Number,PatientId,EncounterId,Status,Discount,TaxRate,CreatedAtUtc,IssuedAtUtc,Version FROM bill.Invoices WHERE HospitalId=@h ORDER BY CreatedAtUtc DESC,Id", r => new Invoice(G(r, "Id"), S(r, "Number"), G(r, "PatientId"), GN(r, "EncounterId"), S(r, "Status"), [], D(r, "Discount"), D(r, "TaxRate"), [], T(r, "CreatedAtUtc"), TN(r, "IssuedAtUtc"), L(r, "Version")), H);
        var lines = await Query("SELECT InvoiceId,ServiceId,Name,Quantity,UnitPrice FROM bill.Lines WHERE HospitalId=@h ORDER BY Id", r => (G(r, "InvoiceId"), new InvoiceLine(G(r, "ServiceId"), S(r, "Name"), I(r, "Quantity"), D(r, "UnitPrice"))), H);
        var payments = await Query("SELECT InvoiceId,Id,Amount,Method,Reference,ReceivedAtUtc,ReceivedBy FROM bill.Payments WHERE HospitalId=@h ORDER BY ReceivedAtUtc,Id", r => (G(r, "InvoiceId"), new Payment(G(r, "Id"), D(r, "Amount"), S(r, "Method"), S(r, "Reference"), T(r, "ReceivedAtUtc"), G(r, "ReceivedBy"))), H);
        return invoices.Select(i => i with
        {
            Lines = lines.Where(l => l.Item1 == i.Id).Select(l => l.Item2).ToList(),
            Payments = payments.Where(x => x.Item1 == i.Id).Select(x => x.Item2).ToList()
        }).ToList();
    }
    public async Task<Chart?> LoadPortalChartAsync(Guid patientId, int limit, CancellationToken ct)
    {
        var patient = await FindPatientAsync(patientId, ct); if (patient is null) return null;
        var take = limit + 1; var patientArg = ("patient", patientId);
        var encounters = await Query($"SELECT TOP(@limit) {EncounterColumns} FROM emr.Encounters WHERE HospitalId=@h AND BranchId=@b AND PatientId=@patient ORDER BY UpdatedAtUtc DESC,Id", MapEncounter, H, Branch, patientArg, ("limit", take));
        encounters = await AttachChildren(encounters, "PatientId=@patient", ct, H, patientArg);
        var appointments = await Query($"SELECT TOP(@limit) {AppointmentColumns} FROM sched.Appointments WHERE HospitalId=@h AND BranchId=@b AND PatientId=@patient ORDER BY StartsAtUtc DESC,Id", MapAppointment, H, Branch, patientArg, ("limit", take));
        var invoices = new List<Invoice>();
        foreach (var id in await Query("SELECT TOP(@limit) Id FROM bill.Invoices WHERE HospitalId=@h AND BranchId=@b AND PatientId=@patient ORDER BY CreatedAtUtc DESC,Id", r => G(r, "Id"), H, Branch, patientArg, ("limit", take)))
            if (await FindInvoiceAsync(id, ct) is { } invoice) invoices.Add(invoice);
        return new Chart(patient, encounters.Take(limit).ToList(), appointments.Take(limit).ToList(), invoices, encounters.Count > limit || appointments.Count > limit || invoices.Count > limit);
    }
